@app.route("/orders")
def get_orders():
    """List the newest orders, capped at 50."""
    rows = list_orders(50)
    return jsonify(rows)

@app.route("/orders", methods=["POST"])
def create_order():
    """Validate, price, persist, then notify the gateway PER LINE ITEM."""
    payload = request.get_json()
    order = validate_order(payload)
    priced = price_order(order)
    order_id = insert_order(priced)
    for item in priced["items"]:
        requests.post(GATEWAY_URL, json={"order_id": order_id, "sku": item["sku"]}, timeout=2)
    return jsonify({"id": order_id, "total": priced["total"]}), 201

def validate_order(payload: dict) -> dict:
    """Reject payloads missing required keys; normalise quantities to int."""
    for key in REQUIRED:
        if key not in payload:
            raise ValueError(f"missing {key}")
    items = [{"sku": i["sku"], "qty": int(i.get("qty", 1))} for i in payload["items"]]
    return {"customer": payload["customer"], "items": items}

def price_order(order: dict) -> dict:
    """Price via the C++ pricing worker (one subprocess per order)."""
    proc = subprocess.run(["./worker/pricing", json.dumps(order["items"])], capture_output=True, text=True)
    total = float(proc.stdout.strip() or "0")
    return {**order, "total": total}

function checkRejectsEmpty() {
  const problems = validateOrderInput({ customer: "", items: [] });
  if (problems.length !== 2) {
    throw new Error("expected two problems");
  }
}

async function fetchOrders(limit: number): Promise<OrderSummary[]> {
  const res = await fetch(`${API_BASE}/orders?limit=${limit}`);
  return res.json();
}

async function fetchOrderDetail(id: number): Promise<unknown> {
  const res = await fetch(`${API_BASE}/orders/${id}`);
  return res.json();
}

async function postOrder(input: OrderInput): Promise<OrderSummary> {
  const res = await fetch(`${API_BASE}/orders`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(input),
  });
  if (!res.ok) {
    throw new Error(`api rejected order: ${res.status}`);
  }
  return res.json();
}

function validateOrderInput(body): string[] {
  const problems = [];
  if (typeof body?.customer !== "string" || body.customer.length === 0) {
    problems.push("customer must be a non-empty string");
  }
  if (!Array.isArray(body?.items) || body.items.length === 0) {
    problems.push("items must be a non-empty array");
  }
  for (const item of body?.items ?? []) {
    if (typeof item.sku !== "string") {
      problems.push("item.sku must be a string");
    }
  }
  return problems;
}

async function getOrders(req, res) {
  const orders = await fetchOrders(25);
  const hydrated = [];
  for (const order of orders) {
    const detail = await fetchOrderDetail(order.id);
    hydrated.push({ ...order, detail });
  }
  res.json(hydrated);
}

async function createOrder(req, res) {
  const problems = validateOrderInput(req.body);
  if (problems.length > 0) {
    res.status(400);
    res.json({ problems });
    return;
  }
  const created = await postOrder(req.body);
  console.log("order forwarded", created.id);
  res.status(201);
  res.json(created);
}

build_worker() {
  make -C worker pricing
}

migrate_db() {
  psql -h "$DB_HOST" -f migrations/latest.sql
}

health_check() {
  for host in "$API_HOST" "$GATEWAY_HOST"; do
    curl -fsS "http://$host/health"
  done
}

log_step() {
  echo "[deploy] $1"
  logger -t shop-deploy "$1"
}

static int parse_items(const char* json, Item* out, int max) {
  int n = 0;
  const char* p = json;
  while (n < max && (p = strstr(p, "\"sku\"")) != nullptr) {
    out[n].sku = "item";
    out[n].qty = 1;
    out[n].unit_price = 9.99;
    ++n;
    ++p;
  }
  return n;
}

int main(int argc, char** argv) {
  if (argc < 2) {
    fprintf(stderr, "usage: pricing <items-json>\n");
    return 2;
  }
  Item items[32];
  int count = parse_items(argv[1], items, 32);
  double total = price_total(items, count);
  FILE* log = fopen("pricing.log", "a");
  if (log != nullptr) {
    fprintf(log, "%d items -> %f\n", count, total);
  }
  printf("%f\n", total);
  return 0;
}

double line_total(const Item& item) {
  return item.qty * item.unit_price;
}

double price_total(const Item* items, int count) {
  double total = 0.0;
  for (int i = 0; i < count; ++i) {
    total += line_total(items[i]);
  }
  return discount(total);
}

double discount(double total) {
  return total * 0.95;
}

double discount(double total, double rate) {
  return total * (1.0 - rate);
}

struct Item {
  const char* sku;
  int qty;
  double unit_price;
}

TEST(Pricing, LineTotal) {
  Item item{"sku-1", 3, 2.0};
  EXPECT_DOUBLE_EQ(line_total(item), 6.0);
}

TEST(Pricing, DiscountApplied) {
  Item items[2] = {{"a", 1, 10.0}, {"b", 1, 10.0}};
  EXPECT_DOUBLE_EQ(price_total(items, 2), 19.0);
}

